     1→module protocol::referral;
     2→
     3→// === Imports ===
     4→
     5→use sui::table::{Self, Table};
     6→use sui::vec_map::{ Self, VecMap };
     7→use sui::balance::{ Balance } ;
     8→use sui::bag::{ Self, Bag };
     9→use sui::coin::Coin;
    10→use sui::random::{Self, Random};
    11→
    12→use std::string::{ Self, String };
    13→use std::type_name::{ Self, TypeName };
    14→
    15→use protocol::error;
    16→use std::option::some;
    17→use std::option::none;
    18→use sui::event::emit;
    19→
    20→// === Constants ===
    21→const DENOMINATOR: u64 = 10000;
    22→const REFERRAL_CODE_LENGTH: u64 = 6;
    23→
    24→public struct ReferralRecordedEvent has copy, drop {
    25→    coin_type: TypeName,
    26→    amount: u64,
    27→    referee: address,
    28→    referer: address,
    29→}
    30→
    31→// === Structs ===
    32→public struct Referral has key, store {
    33→    id: UID,
    34→
    35→    is_claim_paused: bool,
    36→
    37→    code_owner: Table<String, address>,
    38→    referrer_code: Table<address, String>,
    39→
    40→    // the binding between referee to the referral code, this code once binded will not change and will
    41→    // always be used
    42→    referee_to_code: Table<address, String>,
    43→
    44→    referrer_discount_bps: u64,
    45→    referee_discount_bps: u64,
    46→    referrer_deposit_usd_threshold: u64,
    47→
    48→    // only allow referral code generation if deposit usd is more than `referrer_deposit_usd_threshold`
    49→    accumulated_deposit_only_usd: Table<address, u64>,
    50→
    51→    // flash loan coin type to rebate amount
    52→    user_rebates_records: Table<address, VecMap<TypeName, u64>>,
    53→    rebates: Bag,
    54→}
    55→
    56→// === Public Functions ===
    57→public(package) fun has_referral_code(self: &Referral, who: address): bool { self.referrer_code.contains(who) }
    58→
    59→public(package) fun get_referral_code(
    60→    self: &Referral,
    61→    who: address
    62→): String {
    63→    assert!(self.has_referral_code(who), error::referral_no_referral_code());
    64→    *self.referrer_code.borrow(who)
    65→}
    66→
    67→public(package) fun list_rebates(self: &Referral, who: address): (vector<TypeName>, vector<u64>) { 
    68→    let mut coin_types = vector::empty<TypeName>();
    69→    let mut amounts = vector::empty<u64>();
    70→
    71→    // if user has no rebate records, return empty vectors
    72→    if (!self.user_rebates_records.contains(who)) {
    73→        return (coin_types, amounts)
    74→    };
    75→
    76→    let user_rebates = self.user_rebates_records.borrow(who);
    77→    user_rebates.keys().do!(| key | {
    78→        let amount = *user_rebates.get(&key);
    79→        coin_types.push_back(key);
    80→        amounts.push_back(amount);
    81→    });
    82→    
    83→    (coin_types, amounts)
    84→}
    85→
    86→public(package) fun is_qualified_to_create_referral_code(
    87→    self: &Referral, 
    88→    who: address, 
    89→): bool {
    90→    if (!self.accumulated_deposit_only_usd.contains(who)) {
    91→        return false
    92→    };
    93→
    94→    let current = self.accumulated_deposit_only_usd.borrow( who );
    95→    *current >= self.referrer_deposit_usd_threshold
    96→}
    97→
    98→// === Public(Package) Functions ===
    99→public(package) fun default(ctx: &mut TxContext): Referral { new(1000, 400, 10000, ctx) }
   100→
   101→public(package) fun increase_usd_qualification(
   102→    self: &mut Referral, 
   103→    who: address, 
   104→    deposit_usd: u64
   105→) {
   106→    if (!self.accumulated_deposit_only_usd.contains(who)) {
   107→        self.accumulated_deposit_only_usd.add( who, deposit_usd);
   108→        return
   109→    };
   110→
   111→    let current = self.accumulated_deposit_only_usd.borrow_mut( who );
   112→
   113→    // no need accumulation if the amount is more than threshold
   114→    if (*current > self.referrer_deposit_usd_threshold) return;
   115→
   116→    *current = *current + deposit_usd;
   117→}
   118→
   119→public(package) fun track_flash_loan_usage<CoinType>(
   120→    self: &mut Referral,
   121→    mut fee: Coin<CoinType>,
   122→    referral_code: String,
   123→    who: address,
   124→    ctx: &mut TxContext
   125→): Coin<CoinType> {
   126→    // verify referral code exists
   127→    assert!(self.code_owner.contains(referral_code), error::referral_invalid_referral_code());
   128→
   129→    let initial_fee = fee.value();
   130→    let referer = self.look_up_code_owner(referral_code);
   131→
   132→    let referee_rebates_amount = initial_fee * self.referee_discount_bps / DENOMINATOR;
   133→    let referee_rebates = fee.split(referee_rebates_amount, ctx).into_balance();
   134→
   135→    let fee_remaining = initial_fee - referee_rebates_amount;
   136→
   137→    let referrer_rebates_amount = fee_remaining * self.referrer_discount_bps / DENOMINATOR;
   138→    let referrer_rebates = fee.split(referrer_rebates_amount, ctx).into_balance();
   139→
   140→    // record user rebates
   141→    
   142→    self.update_user_rebate<CoinType>(who, referee_rebates);
   143→
   144→    emit(ReferralRecordedEvent {
   145→        coin_type: type_name::with_defining_ids<CoinType>(),
   146→        amount: referrer_rebates.value(),
   147→        referee: who,
   148→        referer,
   149→    });
   150→    self.update_user_rebate<CoinType>(referer, referrer_rebates);
   151→
   152→    fee
   153→}
   154→
   155→public(package) fun generate_referral_code(
   156→    self: &mut Referral,
   157→    random: &Random,
   158→    ctx: &mut TxContext
   159→) {
   160→    let sender = ctx.sender();
   161→    if (self.referrer_code.contains(sender)) {
   162→        abort error::referral_already_has_referral_code()
   163→    };
   164→
   165→    // check deposit threshold
   166→    assert!(self.is_qualified_to_create_referral_code(sender), error::referral_not_qualified_to_gen_code());
   167→    
   168→    // generate unique referral code (keep generating until we find one that doesn't exist)
   169→    let referral_code = generate_random_string(random, REFERRAL_CODE_LENGTH, ctx);
   170→    assert!(!self.code_owner.contains(referral_code), error::referral_invalid_referral_code());
   171→
   172→    // Store the mapping: code -> owner and owner -> code
   173→    self.code_owner.add(referral_code, sender);
   174→    self.referrer_code.add( sender, referral_code);
   175→}
   176→
   177→public(package) fun claim_rebates<CoinType>(
   178→    self: &mut Referral,
   179→    ctx: &mut TxContext
   180→): Coin<CoinType>{
   181→    assert!(!self.is_claim_paused, error::referral_claim_paused());
   182→
   183→    let sender = ctx.sender();
   184→    let coin_type = type_name::with_defining_ids<CoinType>();
   185→
   186→    // note that if the user has rebate, that means there must be coin type token
   187→
   188→    assert!(self.user_rebates_records.contains(sender), error::referral_no_rebates());
   189→
   190→    let user_rebates = self.user_rebates_records.borrow_mut(sender);
   191→    assert!(user_rebates.contains(&coin_type), error::referral_rebate_no_token());
   192→
   193→    let amount = *user_rebates.get(&coin_type);
   194→
   195→    // if the coin type can be found, it must be greater than 0, sanity check, should never hit
   196→    assert!(amount != 0, error::referral_claim_zero_value_rebate());
   197→    user_rebates.remove(&coin_type);
   198→
   199→    // check if balance has enough
   200→    let balance = self.rebates.borrow_mut<TypeName, Balance<CoinType>>(coin_type);  
   201→    balance.split(amount).into_coin(ctx)
   202→}
   203→
   204→/// Checks if the user has already binded with the referral code. If not, binds with the referral code. If maybe_referral is none, but user has
   205→/// binded with existing referral code, then use the bineded referral code.
   206→public(package) fun try_map_referral_code(
   207→    self: &mut Referral,
   208→    user: address,
   209→    maybe_referral: Option<String>,
   210→): Option<String> {
   211→    if (self.referee_to_code.contains(user)) {
   212→        let code = *self.referee_to_code.borrow(user);
   213→        return some(code)
   214→    };
   215→
   216→    if (maybe_referral.is_none()) {
   217→        return maybe_referral
   218→    };
   219→
   220→    let code = *maybe_referral.borrow();
   221→
   222→    assert!(self.code_owner.contains(code), error::referral_invalid_referral_code());
   223→
   224→    let owner = self.code_owner.borrow(code);
   225→    assert!(owner != user, error::referral_no_self_reference());
   226→
   227→    self.referee_to_code.add(user, code);
   228→
   229→    maybe_referral
   230→}
   231→
   232→public(package) fun get_linked_referral_code(
   233→    self: &Referral,
   234→    user: address,
   235→): Option<String> {
   236→    if (self.referee_to_code.contains(user)) {
   237→        let code = *self.referee_to_code.borrow(user);
   238→        some(code)
   239→    } else {
   240→        none()
   241→    }
   242→}
   243→
   244→public(package) fun update_referral_params(
   245→    self: &mut Referral,
   246→    referrer_discount_bps: u64,
   247→    referee_discount_bps: u64,
   248→    referrer_deposit_usd_threshold: u64,
   249→) {
   250→    assert!(referrer_discount_bps < DENOMINATOR, error::invalid_params_error());
   251→    assert!(referee_discount_bps < DENOMINATOR, error::invalid_params_error());
   252→    assert!(referrer_deposit_usd_threshold > 0, error::invalid_params_error());
   253→    self.referrer_discount_bps = referrer_discount_bps;
   254→    self.referee_discount_bps = referee_discount_bps;
   255→    self.referrer_deposit_usd_threshold = referrer_deposit_usd_threshold;
   256→}
   257→
   258→public(package) fun update_claim_pause(
   259→    self: &mut Referral,
   260→    is_pause: bool,
   261→) {
   262→    assert!(self.is_claim_paused != is_pause, error::updating_with_same_value());
   263→    self.is_claim_paused = is_pause;
   264→}
   265→
   266→// === Private Functions ===
   267→fun new(
   268→    referrer_discount_bps: u64,
   269→    referee_discount_bps: u64,
   270→    referrer_deposit_usd_threshold: u64,
   271→    ctx: &mut TxContext
   272→): Referral {
   273→    Referral {
   274→        id: object::new(ctx),
   275→
   276→        is_claim_paused: false,
   277→
   278→        code_owner: table::new(ctx),
   279→        referrer_code: table::new(ctx),
   280→
   281→        referee_to_code: table::new(ctx),
   282→
   283→        referrer_discount_bps,
   284→        referee_discount_bps,
   285→        referrer_deposit_usd_threshold,        
   286→
   287→        accumulated_deposit_only_usd: table::new(ctx),
   288→        user_rebates_records: table::new(ctx),
   289→        rebates: bag::new(ctx),
   290→    }
   291→}
   292→
   293→fun look_up_code_owner(self: &Referral, referral_code: String): address {
   294→    *self.code_owner.borrow(referral_code)
   295→}
   296→
   297→fun update_user_rebate<CoinType>(self: &mut Referral, who: address, rebates: Balance<CoinType>) {
   298→    if (rebates.value() == 0) {
   299→        rebates.destroy_zero();
   300→        return
   301→    };
   302→
   303→    self.record_user_rebates<CoinType>(who, rebates.value());
   304→    self.join_rebate_balance<CoinType>(rebates);
   305→}
   306→
   307→fun record_user_rebates<CoinType>(self: &mut Referral, who: address, amount: u64) {
   308→    let coin_type = type_name::with_defining_ids<CoinType>();
   309→
   310→    if (!self.user_rebates_records.contains(who)) {
   311→        let mut user_rebates = vec_map::empty<TypeName, u64>();
   312→        user_rebates.insert(coin_type, amount);
   313→        self.user_rebates_records.add( who, user_rebates);
   314→        return
   315→    };
   316→
   317→    let user_rebates = self.user_rebates_records.borrow_mut( who);
   318→    if (!user_rebates.contains( &coin_type)) {
   319→        user_rebates.insert( coin_type, amount);
   320→        return
   321→    };
   322→    
   323→    let current = user_rebates.get_mut(&coin_type);
   324→    *current = *current + amount;
   325→}
   326→
   327→fun join_rebate_balance<CoinType>(self: &mut Referral, rebates: Balance<CoinType>) {
   328→    let coin_type = type_name::with_defining_ids<CoinType>();
   329→    if (self.rebates.contains(coin_type)) {
   330→        let balance = self.rebates.borrow_mut<TypeName, Balance<CoinType>>(coin_type);
   331→       balance.join(rebates);
   332→    } else {
   333→        self.rebates.add(coin_type, rebates);
   334→    }
   335→}
   336→
   337→/// generate a random string of specified length using characters a-z and 0-9
   338→fun generate_random_string(
   339→    random: &Random,
   340→    length: u64,
   341→    ctx: &mut TxContext
   342→): String {
   343→    let mut generator = random::new_generator(random, ctx);
   344→    let mut chars   = vector::empty<u8>();
   345→    
   346→    length.do!(|_| {
   347→        // generate random index 0-35 (36 characters: 0-9 + a-z)
   348→        let rand = generator.generate_u8();
   349→        let idx = rand % 36;
   350→        
   351→        let char_byte = if (idx < 10) {
   352→            // 0-9: ASCII 48-57
   353→            48 + idx
   354→        } else {
   355→            // a-z: ASCII 97-122 (idx 10-35 maps to 'a'-'z')
   356→            87 + idx  // 97 - 10 = 87
   357→        };
   358→        chars.push_back(char_byte);
   359→    });
   360→    
   361→    string::utf8(chars)
   362→}
