   364→// === Testing ===
   365→#[test_only]
   366→use sui::{
   367→    test_scenario::{ Self as ts},
   368→    coin::{ Self },
   369→};
   370→// === Test Only Constants ===
   371→#[test_only]
   372→const ADMIN: address = @0x0;
   373→#[test_only]
   374→const USER1: address = @0xB;
   375→#[test_only]
   376→const USER2: address = @0xC;
   377→
   378→// === Test Only Structs ===
   379→#[test_only]
   380→public struct USDC has drop {}
   381→
   382→// === Test Only Functions ===
   383→#[test_only]
   384→fun set_accumulated_deposit_usd_for(self: &mut Referral, who: address, amount: u64) {
   385→    if(self.accumulated_deposit_only_usd.contains(who)) {
   386→        let current = self.accumulated_deposit_only_usd.borrow_mut(who);
   387→        *current = amount;
   388→    } else {
   389→        self.accumulated_deposit_only_usd.add(who, amount);
   390→    };
   391→}
   392→
   393→// === Test Functions ===
   394→#[test]
   395→fun create_referral_test() {
   396→    let mut scenario = ts::begin(ADMIN);
   397→    let ctx = scenario.ctx();
   398→    let referral = new(
   399→        500,  // referrer_discount_bps: 5%
   400→        400,  // referee_discount_bps: 4%
   401→        10_000, // referrer_deposit_usd_threshold: $10000
   402→        ctx
   403→    );
   404→    assert!(referral.referee_discount_bps == 400, 0);
   405→    assert!(referral.referrer_discount_bps == 500, 1);
   406→    assert!(referral.referrer_deposit_usd_threshold == 10_000, 2);
   407→
   408→    std::unit_test::destroy(referral);
   409→    ts::end(scenario);
   410→}
   411→
   412→#[test]
   413→fun track_deposit_usd_test() {
   414→    let mut scenario = ts::begin(ADMIN);
   415→    let ctx = scenario.ctx();
   416→    
   417→    let mut referral = new(
