module protocol::referral;

// === Imports ===

use sui::table::{Self, Table};
use sui::vec_map::{ Self, VecMap };
use sui::balance::{ Balance } ;
use sui::bag::{ Self, Bag };
use sui::coin::Coin;
use sui::random::{Self, Random};

use std::string::{ Self, String };
use std::type_name::{ Self, TypeName };

use protocol::error;
use std::option::some;
use std::option::none;
use sui::event::emit;

// === Constants ===
const DENOMINATOR: u64 = 10000;
const REFERRAL_CODE_LENGTH: u64 = 6;

public struct ReferralRecordedEvent has copy, drop {
    coin_type: TypeName,
    amount: u64,
    referee: address,
    referer: address,
}

// === Structs ===
public struct Referral has key, store {
    id: UID,

    is_claim_paused: bool,

    code_owner: Table<String, address>,
    referrer_code: Table<address, String>,

    // the binding between referee to the referral code, this code once binded will not change and will
    // always be used
    referee_to_code: Table<address, String>,

    referrer_discount_bps: u64,
    referee_discount_bps: u64,
    referrer_deposit_usd_threshold: u64,

    // only allow referral code generation if deposit usd is more than `referrer_deposit_usd_threshold`
    accumulated_deposit_only_usd: Table<address, u64>,

    // flash loan coin type to rebate amount
    user_rebates_records: Table<address, VecMap<TypeName, u64>>,
    rebates: Bag,
}

// === Public Functions ===
public(package) fun has_referral_code(self: &Referral, who: address): bool { self.referrer_code.contains(who) }

public(package) fun get_referral_code(
    self: &Referral,
    who: address
): String {
    assert!(self.has_referral_code(who), error::referral_no_referral_code());
    *self.referrer_code.borrow(who)
}

public(package) fun list_rebates(self: &Referral, who: address): (vector<TypeName>, vector<u64>) { 
    let mut coin_types = vector::empty<TypeName>();
    let mut amounts = vector::empty<u64>();

    // if user has no rebate records, return empty vectors
    if (!self.user_rebates_records.contains(who)) {
        return (coin_types, amounts)
    };

    let user_rebates = self.user_rebates_records.borrow(who);
    user_rebates.keys().do!(| key | {
        let amount = *user_rebates.get(&key);
        coin_types.push_back(key);
        amounts.push_back(amount);
    });

    (coin_types, amounts)
}

public(package) fun is_qualified_to_create_referral_code(
    self: &Referral, 
    who: address, 
): bool {
    if (!self.accumulated_deposit_only_usd.contains(who)) {
        return false
    };

    let current = self.accumulated_deposit_only_usd.borrow( who );
    *current >= self.referrer_deposit_usd_threshold
}

// === Public(Package) Functions ===
public(package) fun default(ctx: &mut TxContext): Referral { new(1000, 400, 10000, ctx) }

public(package) fun increase_usd_qualification(
    self: &mut Referral, 
    who: address, 
    deposit_usd: u64
) {
    if (!self.accumulated_deposit_only_usd.contains(who)) {
        self.accumulated_deposit_only_usd.add( who, deposit_usd);
        return
    };

    let current = self.accumulated_deposit_only_usd.borrow_mut( who );

    // no need accumulation if the amount is more than threshold
    if (*current > self.referrer_deposit_usd_threshold) return;

    *current = *current + deposit_usd;
}

public(package) fun track_flash_loan_usage<CoinType>(
    self: &mut Referral,
    mut fee: Coin<CoinType>,
    referral_code: String,
    who: address,
    ctx: &mut TxContext
): Coin<CoinType> {
    // verify referral code exists
    assert!(self.code_owner.contains(referral_code), error::referral_invalid_referral_code());

    let initial_fee = fee.value();
    let referer = self.look_up_code_owner(referral_code);

    let referee_rebates_amount = initial_fee * self.referee_discount_bps / DENOMINATOR;
    let referee_rebates = fee.split(referee_rebates_amount, ctx).into_balance();

    let fee_remaining = initial_fee - referee_rebates_amount;

    let referrer_rebates_amount = fee_remaining * self.referrer_discount_bps / DENOMINATOR;
    let referrer_rebates = fee.split(referrer_rebates_amount, ctx).into_balance();

    // record user rebates

    self.update_user_rebate<CoinType>(who, referee_rebates);

    emit(ReferralRecordedEvent {
        coin_type: type_name::with_defining_ids<CoinType>(),
        amount: referrer_rebates.value(),
        referee: who,
        referer,
    });
    self.update_user_rebate<CoinType>(referer, referrer_rebates);

    fee
}

public(package) fun generate_referral_code(
    self: &mut Referral,
    random: &Random,
    ctx: &mut TxContext
) {
    let sender = ctx.sender();
    if (self.referrer_code.contains(sender)) {
        abort error::referral_already_has_referral_code()
    };

    // check deposit threshold
    assert!(self.is_qualified_to_create_referral_code(sender), error::referral_not_qualified_to_gen_code());

    // generate unique referral code (keep generating until we find one that doesn't exist)
    let referral_code = generate_random_string(random, REFERRAL_CODE_LENGTH, ctx);
    assert!(!self.code_owner.contains(referral_code), error::referral_invalid_referral_code());

    // Store the mapping: code -> owner and owner -> code
    self.code_owner.add(referral_code, sender);
    self.referrer_code.add( sender, referral_code);
}

public(package) fun claim_rebates<CoinType>(
    self: &mut Referral,
    ctx: &mut TxContext
): Coin<CoinType>{
    assert!(!self.is_claim_paused, error::referral_claim_paused());

    let sender = ctx.sender();
    let coin_type = type_name::with_defining_ids<CoinType>();

    // note that if the user has rebate, that means there must be coin type token

    assert!(self.user_rebates_records.contains(sender), error::referral_no_rebates());

    let user_rebates = self.user_rebates_records.borrow_mut(sender);
    assert!(user_rebates.contains(&coin_type), error::referral_rebate_no_token());

    let amount = *user_rebates.get(&coin_type);

    // if the coin type can be found, it must be greater than 0, sanity check, should never hit
    assert!(amount != 0, error::referral_claim_zero_value_rebate());
    user_rebates.remove(&coin_type);

    // check if balance has enough
    let balance = self.rebates.borrow_mut<TypeName, Balance<CoinType>>(coin_type);  
    balance.split(amount).into_coin(ctx)
}

/// Checks if the user has already binded with the referral code. If not, binds with the referral code. If maybe_referral is none, but user has
/// binded with existing referral code, then use the bineded referral code.
public(package) fun try_map_referral_code(
    self: &mut Referral,
    user: address,
    maybe_referral: Option<String>,
): Option<String> {
    if (self.referee_to_code.contains(user)) {
        let code = *self.referee_to_code.borrow(user);
        return some(code)
    };

    if (maybe_referral.is_none()) {
        return maybe_referral
    };

    let code = *maybe_referral.borrow();

    assert!(self.code_owner.contains(code), error::referral_invalid_referral_code());

    let owner = self.code_owner.borrow(code);
    assert!(owner != user, error::referral_no_self_reference());

    self.referee_to_code.add(user, code);

    maybe_referral
}

public(package) fun get_linked_referral_code(
    self: &Referral,
    user: address,
): Option<String> {
    if (self.referee_to_code.contains(user)) {
        let code = *self.referee_to_code.borrow(user);
        some(code)
    } else {
        none()
    }
}

public(package) fun update_referral_params(
    self: &mut Referral,
    referrer_discount_bps: u64,
    referee_discount_bps: u64,
    referrer_deposit_usd_threshold: u64,
) {
    assert!(referrer_discount_bps < DENOMINATOR, error::invalid_params_error());
    assert!(referee_discount_bps < DENOMINATOR, error::invalid_params_error());
    assert!(referrer_deposit_usd_threshold > 0, error::invalid_params_error());
    self.referrer_discount_bps = referrer_discount_bps;
    self.referee_discount_bps = referee_discount_bps;
    self.referrer_deposit_usd_threshold = referrer_deposit_usd_threshold;
}

public(package) fun update_claim_pause(
    self: &mut Referral,
    is_pause: bool,
) {
    assert!(self.is_claim_paused != is_pause, error::updating_with_same_value());
    self.is_claim_paused = is_pause;
}

// === Private Functions ===
fun new(
    referrer_discount_bps: u64,
    referee_discount_bps: u64,
    referrer_deposit_usd_threshold: u64,
    ctx: &mut TxContext
): Referral {
    Referral {
        id: object::new(ctx),

        is_claim_paused: false,

        code_owner: table::new(ctx),
        referrer_code: table::new(ctx),

        referee_to_code: table::new(ctx),

        referrer_discount_bps,
        referee_discount_bps,
        referrer_deposit_usd_threshold,        

        accumulated_deposit_only_usd: table::new(ctx),
        user_rebates_records: table::new(ctx),
        rebates: bag::new(ctx),
    }
}

fun look_up_code_owner(self: &Referral, referral_code: String): address {
    *self.code_owner.borrow(referral_code)
}

fun update_user_rebate<CoinType>(self: &mut Referral, who: address, rebates: Balance<CoinType>) {
    if (rebates.value() == 0) {
        rebates.destroy_zero();
        return
    };

    self.record_user_rebates<CoinType>(who, rebates.value());
    self.join_rebate_balance<CoinType>(rebates);
}

fun record_user_rebates<CoinType>(self: &mut Referral, who: address, amount: u64) {
    let coin_type = type_name::with_defining_ids<CoinType>();

    if (!self.user_rebates_records.contains(who)) {
        let mut user_rebates = vec_map::empty<TypeName, u64>();
        user_rebates.insert(coin_type, amount);
        self.user_rebates_records.add( who, user_rebates);
        return
    };

    let user_rebates = self.user_rebates_records.borrow_mut( who);
    if (!user_rebates.contains( &coin_type)) {
        user_rebates.insert( coin_type, amount);
        return
    };

    let current = user_rebates.get_mut(&coin_type);
    *current = *current + amount;
}

fun join_rebate_balance<CoinType>(self: &mut Referral, rebates: Balance<CoinType>) {
    let coin_type = type_name::with_defining_ids<CoinType>();
    if (self.rebates.contains(coin_type)) {
        let balance = self.rebates.borrow_mut<TypeName, Balance<CoinType>>(coin_type);
       balance.join(rebates);
    } else {
        self.rebates.add(coin_type, rebates);
    }
}

/// generate a random string of specified length using characters a-z and 0-9
fun generate_random_string(
    random: &Random,
    length: u64,
    ctx: &mut TxContext
): String {
    let mut generator = random::new_generator(random, ctx);
    let mut chars   = vector::empty<u8>();

    length.do!(|_| {
        // generate random index 0-35 (36 characters: 0-9 + a-z)
        let rand = generator.generate_u8();
        let idx = rand % 36;

        let char_byte = if (idx < 10) {
            // 0-9: ASCII 48-57
            48 + idx
        } else {
            // a-z: ASCII 97-122 (idx 10-35 maps to 'a'-'z')
            87 + idx  // 97 - 10 = 87
        };
        chars.push_back(char_byte);
    });

    string::utf8(chars)
}

