   507→fun test_reserve_repay_all() {
   508→    let admin = @0xAD;
   509→    let mut scenario_value = sui::test_scenario::begin(admin);
   510→
   511→    let ctx = scenario_value.ctx();
   512→    let now = 0;
   513→    let mut reserve = new<MainMarket, BTC>(ctx, now);
   514→
   515→    let base = 1000000000;
   516→    let btc = sui::balance::create_for_testing<BTC>(base).into_coin(ctx);
   517→    let ctokens1 = reserve.mint_ctokens<MainMarket, BTC>(btc).into_coin(ctx);
   518→
   519→    let amount = 10000;
   520→    let borrowed_balance = reserve.borrow_amount<MainMarket, BTC>(amount);
   521→
   522→    let reserve_factor = float::from_quotient(1, 100);
   523→    // 5% per year
   524→    let interest_rate = math::float::from_quotient(158548959918, 1000000000000000000);
   525→    let time = 1000; // 1000 seconds
   526→    reserve.accrue_interest(reserve_factor, interest_rate, time);
   527→
   528→    let expected_interest = float::from_quotient(1585489599180000000, 1000000000000000000);
   529→    let expected_debt = float::from(amount).add(expected_interest);
   530→
   531→    assert!(reserve.debt.eq(expected_debt));
   532→    // 1 comes from interest
   533→    assert!(reserve.debt.floor() == amount + 1);
