   303→   303→public(package) fun handle_withdraw<MarketType, CoinType>(
   304→   304→    self: &mut Market<MarketType>,
   305→   305→    obligation_id: ID,
   306→   306→    ctoken_amount: u64,
   307→   307→    coin_decimals_registry: &CoinDecimalsRegistry,
   308→   308→    x_oracle: &XOracle,
   309→   309→    clock: &Clock,
   310→   310→    now: u64,
   311→   311→    ctx: &mut TxContext,
   312→   312→): (Coin<CoinType>, u64) {
   313→   313→    assert!(ctoken_amount != 0, error::no_zero_amount());
   314→   314→
   315→   315→    let name = type_name::with_defining_ids<CoinType>();
   316→   316→
   317→   317→    let asset = self.assets.load_by_type(name);
   318→   318→    assert!(!asset.withdraw_paused(), error::withdraw_paused_for_asset());
