   328→   328→    let ctoken = obligation.withdraw_ctokens(ctoken_amount);
   329→   329→    let ctokens_left = obligation.ctoken_amount_by_coin(name);
   330→   330→
   331→   331→    // TODO: if the asset is not collateral, skip obligation safety check
   332→   332→    let is_obligation_safe = is_obligation_safe(
   333→   333→        self.emode_group_registry.borrow_emode_group(obligation.emode_group()),
   334→   334→        &self.reserves,
   335→   335→        &self.ema_spot_tolerance,
   336→   336→
   337→   337→        obligation,
   338→   338→        coin_decimals_registry,
   339→   339→        x_oracle,
   340→   340→        clock,
   341→   341→    );
   342→   342→    assert!(is_obligation_safe, error::obligation_not_safe_after_operation());
   343→   343→
   344→   344→    let reserve = self.reserves.load_mut_by_type(name);
   345→   345→    let deposit = reserve.burn_ctokens<MarketType, CoinType>(ctoken.into_coin(ctx));
   346→   346→
   347→   347→    // rate limit deposit withdraw
   348→   348→    let emode = self.emode_group_registry.borrow_mut_emode(obligation.emode_group(), type_name::with_defining_ids<CoinType>());
   349→   349→    emode.borrow_mut_deposit_limiter().add_outflow(
   350→   350→        now,
   351→   351→        deposit.value(),
   352→   352→    );
   353→   353→
   354→   354→    // update adl
   355→   355→
   356→   356→    // use ceiling, slighly more 
   357→   357→    let total_deposit = reserve.total_deposit_plus_interest().ceil();
   358→   358→    let adl = dynamic_field::borrow_mut<ADLRegistryKey, AutoDeleverageRegistry>(&mut self.id, ADLRegistryKey {});
   359→   359→    adl.try_stop_collateral_deleverage<CoinType>(type_name::with_defining_ids<MarketType>(), total_deposit);
   360→   360→
   361→   361→
   362→   362→
   363→   363→    (deposit.into_coin(ctx), ctokens_left)
   364→   364→}
