   418→   418→
   419→   419→
   420→   420→    // make sure the emode group borrow limit is not breached
   421→   421→    let emode_group_total_borrow = emode_group.update_asset_borrow(name, obligation_old_total_borrow_amount, obligation_new_total_borrow_amount);
   422→   422→    assert!(emode_group_total_borrow.le(math::float::from(emode_max_borrow_amount)), error::emode_borrow_limit_exceeded());
   423→   423→
   424→   424→    let is_obligation_safe = is_obligation_safe(
