   445→   445→public(package) fun handle_repay<MarketType, CoinType>(
   446→   446→    self: &mut Market<MarketType>,
   447→   447→    obligation_id: ID,
   448→   448→    mut coin: Coin<CoinType>,
   449→   449→    now: u64,
   450→   450→    ctx: &mut TxContext,
   451→   451→): (Coin<CoinType>, Decimal, Decimal) {
   452→   452→    assert!(coin.value() != 0, error::no_zero_amount());
   453→   453→
   454→   454→    let name = type_name::with_defining_ids<CoinType>();
   455→   455→
   456→   456→    let asset = self.assets.load_mut_by_type(name);
   457→   457→    let min_borrow_amount = asset.asset_config().min_borrow_amount();
   458→   458→
   459→   459→    let reserve = accrue_interest<MarketType>(name, &mut self.reserves, asset.asset_config(), asset.interest_model(), now);
   460→   460→    
   461→   461→    let obligation = self.obligations.borrow_mut(obligation_id);
   462→   462→    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());
   463→   463→
   464→   464→
   465→   465→    let obligation_old_borrow_amount = obligation.debt(name).unsafe_debt_amount();
   466→   466→
   467→   467→
   468→   468→    let borrow_index = reserve.borrow_index().value();
   469→   469→    let residule = obligation.repay_debt<MarketType, CoinType>(coin.value(), borrow_index);
   470→   470→    obligation.enforce_post_borrow_repay_invariant<MarketType, CoinType>(min_borrow_amount);
   471→   471→    
   472→   472→    // interest updated, should be up to date
   473→   473→    let obligation_new_borrow_amount = if (obligation.has_debt(name)) obligation.debt(name).unsafe_debt_amount() else float::zero();
   474→   474→
   475→   475→    let refund = coin.split(residule, ctx);
   476→   476→
   477→   477→    let emode_group_id = obligation.emode_group();
   478→   478→
   479→   479→    let emode_group = self.emode_group_registry.borrow_emode_group_mut(emode_group_id);
   480→   480→    let emode_group_total_borrow = emode_group.update_asset_borrow(name, obligation_old_borrow_amount, obligation_new_borrow_amount);
   481→   481→
   482→   482→    let emode = emode_group.borrow_emode_mut(name);
   483→   483→    emode.borrow_mut_borrow_limiter().reduce_outflow(now, coin.value());
   484→   484→
   485→   485→
   486→   486→    reserve.repay_amount(coin);
   487→   487→
   488→   488→    // try stop adl, if there is one on going
   489→   489→    let adl = dynamic_field::borrow_mut<ADLRegistryKey, AutoDeleverageRegistry>(&mut self.id, ADLRegistryKey {});
   490→   490→    // use ceiling, slighly more 
   491→   491→    adl.try_stop_borrow_deleverage<CoinType>(type_name::with_defining_ids<MarketType>(), emode_group_id, emode_group_total_borrow.ceil());
   492→   492→
   493→   493→    (refund, borrow_index, obligation_new_borrow_amount)
   494→   494→}
