   503→   503→    now: u64,
   504→   504→    ctx: &mut TxContext,
   505→   505→): (Coin<CollateralType>, Coin<DebtType>, u64) {
   506→   506→    let MarketConfiguration { close_factor, close_factor_bypass_min_value } = *self.market_config();
   507→   507→
   508→   508→    let obligation = self.obligations.borrow_mut(obligation_id);
