   546→   546→public(package) fun handle_debt_auto_deleverage<MarketType, DebtType, CollateralType>(
   547→   547→    self: &mut Market<MarketType>,
   548→   548→    obligation_id: ID,
   549→   549→    available_repay_coin: Coin<DebtType>,
   550→   550→    coin_decimals_registry: &CoinDecimalsRegistry,
   551→   551→    x_oracle: &XOracle,
   552→   552→    clock: &Clock,
   553→   553→    now: u64,
   554→   554→    ctx: &mut TxContext,
   555→   555→): (Coin<CollateralType>, Coin<DebtType>, u64) {
   556→   556→    let close_factor_bypass_min_value = self.market_config().close_factor_bypass_min_value;
   557→   557→
   558→   558→    let debt_type = type_name::with_defining_ids<DebtType>();
   559→   559→    let collateral_type = type_name::with_defining_ids<CollateralType>();
   560→   560→
   561→   561→    let obligation = self.obligations.borrow_mut(obligation_id);
   562→   562→    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());
   563→   563→
   564→   564→    let emode_group_id = obligation.emode_group();
   565→   565→    let emode_group = self.emode_group_registry.borrow_emode_group_mut(obligation.emode_group());
   566→   566→
   567→   567→    let collateral_setting = emode_group.borrow_emode(collateral_type).collateral();
   568→   568→    // cannot liquidate asset that is not collateral
   569→   569→    assert!(collateral_setting.can_be_collateral(), error::asset_not_collateral());
   570→   570→
   571→   571→    let max_liquidation_incentive = collateral_setting.liquidation_incentive();
   572→   572→
   573→   573→
   574→   574→    let adl_registry = dynamic_field::borrow<ADLRegistryKey, AutoDeleverageRegistry>(&self.id, ADLRegistryKey {});
   575→   575→    let timelock = *adl_registry.get_borrow_deleverage(debt_type, emode_group_id);
   576→   576→
   577→   577→    let asset = self.assets.load_mut_by_type(debt_type);
   578→   578→    accrue_interest<MarketType>(debt_type, &mut self.reserves, asset.asset_config(), asset.interest_model(), now);
   579→   579→
   580→   580→    let total_debt = (*self.reserves.load_by_type(debt_type).debt()).floor();
   581→   581→    let debt_params = timelock.inner();
   582→   582→    debt_params.ensure_limit_breached(total_debt);
   583→   583→
   584→   584→
   585→   585→    let activation_time = timelock.get_secs_since_activation(clock);
   586→   586→    let liquidation_params = LiquidationParams {
   587→   587→        liquidation_ltv_threshold_override: std::option::some(debt_params.liquidation_ltv(activation_time)),
   588→   588→        // adl liquidation_incentive should not have exceeded non-adl liquidation_incentive
   589→   589→        liquidation_incentive: debt_params.liquidation_incentive(activation_time).min(max_liquidation_incentive),
   590→   590→        liquidation_revenue_factor: float::zero(),
   591→   591→        close_factor: debt_params.close_factor(),
   592→   592→        close_factor_bypass_min_value,
   593→   593→    };
   594→   594→
   595→   595→
   596→   596→
   597→   597→    liquidation_inner<MarketType, DebtType, CollateralType>(
   598→   598→        &mut self.id,
   599→   599→        &self.assets,
   600→   600→        emode_group,
   601→   601→        &mut self.reserves,
   602→   602→        obligation,
   603→   603→        &liquidation_params,
   604→   604→        available_repay_coin,
   605→   605→        coin_decimals_registry,
   606→   606→        x_oracle,
   607→   607→        clock,
   608→   608→        now,
   609→   609→        ctx,
   610→   610→    )
   611→   611→}
