   691→   691→fun liquidation_inner<MarketType, DebtType, CollateralType>(
   692→   692→    id: &mut UID,
   693→   693→
   694→   694→    assets: &GenericCoinTypeStorage<Asset<MarketType>>,
   695→   695→    emode_group: &mut EModeGroup,
   696→   696→
   697→   697→    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,
   698→   698→
