623→    let close_factor_bypass_min_value = self.market_config().close_factor_bypass_min_value;
624→
625→    let collateral = type_name::with_defining_ids<CollateralType>();
626→
627→    // load the time locked adl params
628→    let adl_registry = self.adl_registry<MarketType>();
629→    let timelock = *adl_registry.get_collateral_deleverage(collateral);
630→
631→    // refresh obligation
632→    let obligation = self.obligations.borrow_mut(obligation_id);
