652→    let activation_time = timelock.get_secs_since_activation(clock);
653→
654→    let liquidation_params = LiquidationParams {
655→        liquidation_ltv_threshold_override: std::option::some(collateral_params.liquidation_ltv(activation_time)),
656→        // adl liquidation_incentive should not have exceeded non-adl liquidation_incentive
657→        liquidation_incentive: collateral_params.liquidation_incentive(activation_time).min(max_liquidation_incentive),
658→        liquidation_revenue_factor: float::zero(),
