   926→   926→/// Make sure the caller has refresh all obligation debt and collateral interest before calling this method
   927→   927→fun ensure_liquidate_borrow_allowed<MarketType, DebtType>(
   928→   928→    liquidation_params: &LiquidationParams,
   929→   929→
   930→   930→    obligation: &Obligation<MarketType>,
   931→   931→
   932→   932→    emode_group: &EModeGroup,
   933→   933→
   934→   934→    reserves: &GenericCoinTypeStorage<Reserve<MarketType>>,
   935→   935→
   936→   936→    coin_decimals_registry: &CoinDecimalsRegistry,
   937→   937→    liquidator_repay_amount: u64,
   938→   938→
   939→   939→    x_oracle: &XOracle,
   940→   940→
   941→   941→    clock: &Clock,
   942→   942→) {
   943→   943→    // make sure that their obligation still healthy, so users aren't borrowing over their collateral
   944→   944→    let (weighted_debts_value, debts_total_value) = debts_value_usd_for_liquidation(
   945→   945→        emode_group,
   946→   946→        reserves,
   947→   947→        obligation,
   948→   948→        coin_decimals_registry,
   949→   949→        x_oracle,
   950→   950→        clock,
   951→   951→    );
   952→   952→
   953→   953→    let (collateral_weighted_value, collateral_total_value) = collaterals_usd_for_liquidation(
   954→   954→        emode_group,
   955→   955→        reserves,
   956→   956→        obligation,
   957→   957→        coin_decimals_registry,
   958→   958→        x_oracle,
   959→   959→        clock,
   960→   960→    );
   961→   961→
   962→   962→    // triggering condition: 
   963→   963→    // user_ltv > liquidation_ltv
   964→   964→    if (liquidation_params.liquidation_ltv_threshold_override.is_some()) {
   965→   965→        let liquidation_ltv = *liquidation_params.liquidation_ltv_threshold_override.borrow();
   966→   966→        let user_ltv = weighted_debts_value.div(collateral_total_value);
   967→   967→        assert!(
   968→   968→            user_ltv.gt(liquidation_ltv),
   969→   969→            error::liquidation_obligation_still_safe(),
   970→   970→        );
   971→   971→    } else {
   972→   972→        // user_ltv = weighted_debts_value / collateral_total_value
   973→   973→        // liquidation_ltv = collateral_weighted_value / collateral_total_value
   974→   974→        // user_ltv > liquidation_ltv
   975→   975→        //    weighted_debts_value / collateral_total_value > collateral_weighted_value / collateral_total_value
   976→   976→        //    weighted_debts_value / collateral_weighted_value > liquidation_ltv_threshold
   977→   977→        //    weighted_debts_value > collateral_weighted_value * liquidation_ltv_threshold
   978→   978→        assert!(
   979→   979→            weighted_debts_value.gt(collateral_weighted_value),
   980→   980→            error::liquidation_obligation_still_safe(),
   981→   981→        );
   982→   982→    };
   983→   983→
   984→   984→    // Note that the close factor is enforce ONLY when the obligation is not close to bad debt
   985→   985→    let bad_debt_close_factor_bypass_threshold = float::from_quotient(101, 100);
   986→   986→    let bad_debt_threshold = bad_debt_close_factor_bypass_threshold.mul(debts_total_value);
   987→   987→
   988→   988→    if (collateral_total_value.le(bad_debt_threshold)) {
   989→   989→        // This means the obligation is close to bad debt, allow close whatever is passed
   990→   990→        // close factor effectively equals to 1.
   991→   991→        return
   992→   992→    };
   993→   993→
   994→   994→    let target_debt_type = type_name::with_defining_ids<DebtType>();
   995→   995→
   996→   996→    let debt_balance = obligation.debt(target_debt_type).unsafe_debt_amount();
   997→   997→    let debt_value = coin_value(
   998→   998→        get_price(x_oracle, target_debt_type, emode_group.get_oracle_base_token(), clock),
   999→   999→        debt_balance,
  1000→  1000→        coin_decimals_registry.decimals(target_debt_type)
  1001→  1001→    )
  1002→  1002→        // this is tricky, because it is using ceiling, this mean if the debt value is say 9.8, the ceiling is 10
  1003→  1003→        .ceil();
  1004→  1004→
  1005→  1005→    // below min usd for close factor enforcement
  1006→  1006→    if (debt_value <= liquidation_params.close_factor_bypass_min_value) { return };
  1007→  1007→
  1008→  1008→    let max_debt_amount = debt_balance.mul(liquidation_params.close_factor);
  1009→  1009→    assert!(
  1010→  1010→        math::float::from(liquidator_repay_amount).le(max_debt_amount),
  1011→  1011→        error::liquidation_close_factor_exceeded(),
  1012→  1012→    );
  1013→  1013→}
